import fs from "node:fs";
import path from "node:path";
import { fileURLToPath } from "node:url";
import { normalizeCode } from "../src/data/prerequisites.js";

const REPO_ROOT = path.resolve(path.dirname(fileURLToPath(import.meta.url)), "..");

/** Generated by scripts/buildSyllabusText.js. Direct code lookup only. */
export const SYLLABUS_TEXT_PATH = path.join(REPO_ROOT, "data", "syllabusText.json");

/**
 * Default index path, unless SYLLABUS_TEXT_PATH points at another file.
 * @returns {string}
 */
export function resolveSyllabusTextPath() {
  return process.env.SYLLABUS_TEXT_PATH || SYLLABUS_TEXT_PATH;
}

/**
 * @param {string} filePath
 * @returns {Map<string, string>}
 */
function readIndex(filePath) {
  /** @type {Map<string, string>} */
  const map = new Map();
  let raw;
  try {
    raw = fs.readFileSync(filePath, "utf8");
  } catch {
    return map;
  }

  let rows;
  try {
    rows = JSON.parse(raw);
  } catch {
    return map;
  }
  if (!Array.isArray(rows)) return map;

  for (const row of rows) {
    if (!row || typeof row.code !== "string" || typeof row.text !== "string") continue;
    const text = row.text.trim();
    if (!text) continue;
    map.set(normalizeCode(row.code), text);
  }
  return map;
}

/**
 * Length-capped syllabus text for a catalog course code, or null if it isn't indexed.
 * Plain lookup — no similarity search and no embedding math.
 * @param {string} code
 * @returns {string | null}
 */
export function getSyllabusText(code) {
  if (!code) return null;
  const text = readIndex(resolveSyllabusTextPath()).get(normalizeCode(code));
  return text || null;
}
